import XCTest
@testable import MirNavigation

final class CapturedHarvestTests:XCTestCase {
    func testServerHarvestAnimationAndItems() throws {
        let frames:[String] = [
    "7a41723f74716a6868655a6f6665686a",
    "7a41723f74716a6868655a6f6665686a",
    "7a41723f74716a6868655a6f6665686a",
    "",
    "6b4d5a69615d685f6b655b736665686b676448436464686b64644b",
    "7a41723f74716a6868655a6f6665686a",
    "6b4d5a69615d685f6b655b736665686b676448436464686b64644b",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "7a41723f74716a685f65587b6667686a",
    "",
    "563c404c775d68675e653f7b6667686b676449436464686b64644b",
    "7a41723f74716a685f65587b6667686a"
]
        var meats=Set<Int32>(),corpses=Set<Int32>(),cuts=0
        for hex in frames {
            let chars=Array(hex)
            let raw=stride(from:0,to:chars.count,by:2).map { UInt8(String(chars[$0...$0+1]),radix:16)! }
            let p=try MirWire.packet(raw)
            if p.id==200 { let item=try XCTUnwrap(MirEquipment.item(p.body));XCTAssertEqual(item.mode,40);meats.insert(item.id) }
            if p.id==33 { XCTAssertEqual(p.body.count,8);corpses.insert(p.actor) }
            if p.id==637 { XCTAssertTrue(p.body.isEmpty);XCTAssertLessThan(p.series,8);cuts+=1 }
        }
        XCTAssertEqual(meats.count,2);XCTAssertEqual(corpses.count,2);XCTAssertGreaterThanOrEqual(cuts,16)
    }
}
